from typing import List, Tuple
from collections import defaultdict

def countVertex(N: int, edges: List[Tuple[int, int]]) -> int:
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    def dfs(node, parent):
        leaf = True
        for neighbor in graph[node]:
            if neighbor != parent:
                leaf = False
                if dfs(neighbor, node):
                    nonlocal result
                    result += 1
        return leaf

    result = 0
    dfs(1, -1)
    return result
